// Runnable demo: poison-pill handling, retry-with-backoff, classify, DLT routing.
package com.bank.settlement.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DltDemo {

    private static final Logger log = Logger.getLogger("DLT");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DeadLetterPublisher dlt = new DeadLetterPublisher();
        SettlementListener listener = new SettlementListener();
        DefaultErrorHandlerSim handler = new DefaultErrorHandlerSim(/*attempts*/ 3, dlt);

        // Three raw records on the wire.
        List<String> wire = List.of(
            "{\"txnId\":\"TXN-1\",\"accountId\":\"SAV2001\",\"amount\":20000}", // good
            "{bad json ::: not parseable",                                      // poison pill
            "{\"txnId\":\"TXN-3\",\"accountId\":\"CUR3001\",\"amount\":50000}"  // transient fail then ok
        );

        for (String raw : wire) {
            // ErrorHandlingDeserializer step: try to parse; failure -> FailedRecord.
            TxnEvent event;
            try {
                event = WrappedDeserializer.deserialize(raw);
            } catch (DeserializationException de) {
                log.warning(() -> "deserialization failed (poison pill) for payload=" + raw);
                handler.handle(raw, de, () -> { throw de; });  // non-retryable → straight to DLT
                continue;
            }
            // Listener step, wrapped in the error handler for retry/classify/DLT.
            handler.handle(raw, null, () -> listener.onTxn(event));
        }

        log.info(() -> "DLT contents = " + dlt.count() + " record(s)");
    }
}

// ─── Would be in TxnEvent.java ───
class TxnEvent {
    final String txnId;
    final String accountId;
    final BigDecimal amount;
    TxnEvent(String txnId, String accountId, BigDecimal amount) {
            this.txnId = txnId;
            this.accountId = accountId
            this.amount = amount;
    }
}

// ─── Would be in DeserializationException.java (Spring provides this) ───
class DeserializationException extends RuntimeException {
    DeserializationException(String m) { super(m); }
}

// transient, retryable error
class TransientDbException extends RuntimeException {
    TransientDbException(String m) { super(m); }
}

// ─── Would be in WrappedDeserializer.java (models ErrorHandlingDeserializer) ───
class WrappedDeserializer {
    static TxnEvent deserialize(String raw) {
        if (!raw.trim().startsWith("{\"")) {
            throw new DeserializationException("invalid JSON: " + raw);
        }
        String txn = field(raw, "txnId");
        String acc = field(raw, "accountId");
        BigDecimal amt = new BigDecimal(field(raw, "amount"));
        return new TxnEvent(txn, acc, amt);
    }
    private static String field(String json, String key) {
        int i = json.indexOf("\"" + key + "\"");
        int c = json.indexOf(':', i); int s = c + 1;
        while (json.charAt(s) == ' ' || json.charAt(s) == '"') s++;
        int e = s; while (e < json.length() && "\",}".indexOf(json.charAt(e)) < 0) e++;
        return json.substring(s, e);
    }
}

// ─── Would be in SettlementListener.java ───
class SettlementListener {
    private static final Logger log = Logger.getLogger("DLT");
    private int txn3Attempts = 0;
    void onTxn(TxnEvent e) {
        // TXN-3 fails transiently on the first attempt, then succeeds.
        if ("TXN-3".equals(e.txnId) && txn3Attempts++ == 0) {
            throw new TransientDbException("DB timeout settling " + e.txnId);
        }
        log.info(() -> "settled txn=" + e.txnId + " account=" + e.accountId
                + " amount=Rs." + e.amount);
    }
}

