// Models DefaultErrorHandler: retry+backoff, classify, recover to DLT.
class DefaultErrorHandlerSim {
    private static final Logger log = Logger.getLogger("DLT");
    private final int maxAttempts;
    private final DeadLetterPublisher dlt;
    DefaultErrorHandlerSim(int maxAttempts, DeadLetterPublisher dlt) {
        this.maxAttempts = maxAttempts; this.dlt = dlt;
    }

    void handle(String raw, RuntimeException deserError, Runnable work) {
        if (deserError != null) {               // deserialization = NON-retryable
            log.severe(() -> "non-retryable " + deserError.getClass().getSimpleName()
                    + "; skip retries → DLT");
            dlt.publish(raw, deserError);
            return;
        }
        RuntimeException last = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                work.run();
                return;                          // success, nothing to recover
            } catch (TransientDbException ex) {  // retryable
                last = ex;
                final int a = attempt;
                log.warning(() -> "retryable failure attempt " + a + "/" + maxAttempts
                        + ": " + ex.getMessage() + " (backoff 1000ms)");
            } catch (RuntimeException ex) {      // unknown → treat as fatal
                log.severe(() -> "non-retryable " + ex.getClass().getSimpleName() + " → DLT");
                dlt.publish(raw, ex);
                return;
            }
        }
        log.severe("retries exhausted → DLT");
        dlt.publish(raw, last);
    }
}

// ─── Would be in DeadLetterPublisher.java (models DeadLetterPublishingRecoverer) ───
class DeadLetterPublisher {
    private static final Logger log = Logger.getLogger("DLT");
    private final List<String> dlt = new ArrayList<>();
    void publish(String raw, RuntimeException cause) {
        dlt.add(raw);
        log.severe(() -> "published to txn.events.DLT payload=" + raw
                + " errorClass=" + (cause == null ? "unknown" : cause.getClass().getName()));
    }
    int count() { return dlt.size(); }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
